import React, { useEffect, useState } from "react";
import axios from "axios";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import StatCard from "./ui/StatCard";
import AlertBox from "./AlertBox";
import { FaClipboardList, FaUpload, FaBook } from "react-icons/fa";
import "./theme.css";

function AssignmentsStudent() {
  const studentId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [files, setFiles] = useState({});
  const [selectedCourseId, setSelectedCourseId] = useState("");
  const [selectedSubjectCode, setSelectedSubjectCode] = useState("");
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    loadCourses();
  }, []);

  const loadCourses = async () => {
    const coursesRes = await axios.get("http://127.0.0.1:8000/courses");
    const enrollRes = await axios.get(
      `http://127.0.0.1:8000/enrollments/${studentId}`
    );

    const enrolledIds = enrollRes.data.map((e) => e.course_id);

    setCourses(
      (coursesRes.data.courses || []).filter((c) =>
        enrolledIds.includes(c.id)
      )
    );
  };

  const loadAssignments = async (subjectCode) => {
    if (!subjectCode) {
      setAssignments([]);
      return;
    }

    const res = await axios.get(
      `http://127.0.0.1:8000/assignments/${subjectCode}`
    );

    setAssignments(res.data.assignments || []);
  };

  const handleCourseChange = (e) => {
    const courseId = e.target.value;
    setSelectedCourseId(courseId);

    const selectedCourse = courses.find(
      (c) => String(c.id) === String(courseId)
    );

    const subjectCode = selectedCourse?.subject_code || "";
    setSelectedSubjectCode(subjectCode);
    loadAssignments(subjectCode);
  };

  const handleSubmit = async (assignmentId) => {
    try {
      const file = files[assignmentId];

      if (!file) {
        setAlert({ message: "Select file first", type: "error" });
        return;
      }

      const formData = new FormData();
      formData.append("assignment_id", assignmentId);
      formData.append("student_id", studentId);
      formData.append("file", file);

      const res = await axios.post(
        "http://127.0.0.1:8000/submit-assignment",
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data"
          }
        }
      );

      setAlert({ message: res.data.message, type: "success" });
      window.dispatchEvent(new Event("plannerUpdated"));
    } catch (err) {
      console.error(err);
      setAlert({ message: "Submission failed", type: "error" });
    }
  };

  return (
    <AppShell
      title="Assignments"
      subtitle="Upload your answer files as PDF or image for enrolled subjects."
    >
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div className="page-grid-3" style={{ marginBottom: "20px" }}>
        <StatCard
          icon={<FaBook />}
          label="Courses"
          value={courses.length}
          hint="Courses you're enrolled in"
        />
        <StatCard
          icon={<FaClipboardList />}
          label="Assignments"
          value={assignments.length}
          hint="Assignments in selected subject"
        />
        <StatCard
          icon={<FaUpload />}
          label="Subject Code"
          value={selectedSubjectCode || "N/A"}
          hint="Current selected subject"
        />
      </div>

      <Panel title="Select Course">
        <select
          className="select"
          value={selectedCourseId}
          onChange={handleCourseChange}
        >
          <option value="">Select Course</option>
          {courses.map((c) => (
            <option key={c.id} value={c.id}>
              {c.title} ({c.subject_code})
            </option>
          ))}
        </select>
      </Panel>

      <div style={{ marginTop: "18px" }}>
        <Panel title="Assignments">
          {!selectedSubjectCode ? (
            <p className="muted">Select a course first.</p>
          ) : assignments.length === 0 ? (
            <p className="muted">No assignments found for this subject.</p>
          ) : (
            assignments.map((a) => (
              <div className="list-card" key={a.id}>
                <h4 style={{ marginTop: 0 }}>{a.title}</h4>
                <div className="muted">{a.description}</div>
                <div className="muted" style={{ marginTop: "8px" }}>
                  Due: {a.due_date}
                </div>

                <input
                  type="file"
                  style={{
                    marginTop: "12px",
                    marginBottom: "12px",
                    color: "var(--text)"
                  }}
                  onChange={(e) =>
                    setFiles({ ...files, [a.id]: e.target.files[0] })
                  }
                />

                <button
                  className="btn btn-primary"
                  onClick={() => handleSubmit(a.id)}
                >
                  Upload Answer
                </button>
              </div>
            ))
          )}
        </Panel>
      </div>
    </AppShell>
  );
}

export default AssignmentsStudent;
